const folder = "week6";
console.log(`backticks : ${folder}/generated`);
console.log("quotes    : ${folder}/generated");   // literal, not substituted
console.log(`arithmetic and calls work too: ${folder.toUpperCase()}, ${2 + 3}`);

// Run a real program and read its output.
const gitVersion = new Deno.Command("git", {
  args: ["--version"],
  stdout: "piped",
  stderr: "piped",
});
const result = await gitVersion.output();

console.log("exit code:", result.code);
console.log("stdout   :", new TextDecoder().decode(result.stdout).trim());

// A deliberately failing command, to see the other outcome.
const bad = new Deno.Command("git", {
  args: ["rev-parse", "--verify", "definitely-not-a-branch"],
  stdout: "piped",
  stderr: "piped",
});
const badResult = await bad.output();

console.log("exit code:", badResult.code, "<- non-zero means failure");
console.log("stderr   :", new TextDecoder().decode(badResult.stderr).trim().split("\n")[0]);

import { writeProjectFile, REPO_ROOT } from "../_shared/deno-helpers.ts";

// Runs git for real in a temp folder, then cleans up.

// Backslashes before ` and ${ because the file sits inside a template literal.

await writeProjectFile("week6/generated/day3-git-walkthrough.ts", `// Week 6, Day 3 — every Git command from the session, actually executed.
//
// SAFETY: this builds a throwaway repository in a temp folder and a second one to
// act as "GitHub". It never touches this project or its real remote. You can run it
// as many times as you like.
//
//   deno run -A week6/generated/day3-git-walkthrough.ts
//
// Written by a cell in week6/day3_2.ipynb.

/** Run a command and print it the way a terminal would. */
async function run(cmd: string, args: string[], cwd: string): Promise<string> {
  const p = new Deno.Command(cmd, { args, cwd, stdout: "piped", stderr: "piped" });
  const { stdout, stderr } = await p.output();
  const out = (new TextDecoder().decode(stdout) + new TextDecoder().decode(stderr)).trim();
  console.log(\`$ \${cmd} \${args.join(" ")}\`);
  if (out) console.log(out.split("\\n").map((l) => "  " + l).join("\\n"));
  return out;
}

// Identity passed per-command so nothing is written to your global git config.
const WHO = ["-c", "user.email=learner@example.com", "-c", "user.name=learner"];

const root = await Deno.makeTempDir({ prefix: "week6-git-" });
const work = \`\${root}/playwright_training\`;
const remote = \`\${root}/origin.git\`;
await Deno.mkdir(work);

console.log("=== 1. A bare repo to stand in for GitHub ===");
// A real GitHub repository is a "bare" repo: history, no working files.
await run("git", ["init", "--bare", "-b", "master", remote], root);

console.log("\\n=== 2. git init — turn a folder into a repository ===");
await run("git", ["init", "-b", "master", "."], work);

await Deno.writeTextFile(\`\${work}/package.json\`, JSON.stringify({
  name: "playwright_training",
  scripts: { "zerobank_headless": "playwright test --config=zerobank.config.ts" },
}, null, 2) + "\\n");
await Deno.writeTextFile(\`\${work}/login.spec.ts\`, "// a test file\\n");

console.log("\\n=== 3. git remote add origin — point it at the remote ===");
await run("git", ["remote", "add", "origin", remote], work);
await run("git", ["remote", "-v"], work);

console.log("\\n=== 4. git status — what is not yet tracked ===");
await run("git", ["status", "--short"], work);
console.log("  (?? means untracked — git can see the file but is not storing it)");

console.log("\\n=== 5. git add -A — stage everything ===");
await run("git", ["add", "-A"], work);
await run("git", ["status", "--short"], work);
console.log("  (A means added/staged — staged, but not yet committed)");

console.log("\\n=== 6. git commit -m — save a snapshot ===");
await run("git", [...WHO, "commit", "-m", "adding new project"], work);

console.log("\\n=== 7. git push -u origin master — send it to the remote ===");
await run("git", [...WHO, "push", "-u", "origin", "master"], work);

console.log("\\n=== 8. Someone else clones, changes a file, and pushes ===");
const mate = \`\${root}/teammate\`;
await run("git", ["clone", remote, mate], root);
await Deno.writeTextFile(\`\${mate}/playwright.config.ts\`, "// added by a teammate\\n");
await run("git", ["add", "-A"], mate);
await run("git", [...WHO, "commit", "-m", "add config"], mate);
await run("git", [...WHO, "push", "origin", "master"], mate);

console.log("\\n=== 9. Your copy does not have their file yet ===");
console.log(\`  playwright.config.ts present locally? \${
  await Deno.stat(\`\${work}/playwright.config.ts\`).then(() => "yes").catch(() => "NO")
}\`);

console.log("\\n=== 10. git pull origin master — collect their work ===");
await run("git", [...WHO, "pull", "origin", "master"], work);
console.log(\`  playwright.config.ts present now? \${
  await Deno.stat(\`\${work}/playwright.config.ts\`).then(() => "yes").catch(() => "NO")
}\`);

console.log("\\n=== 11. Why 'pull before push' is the rule ===");
// Both sides change the same file, without pulling first.
await Deno.writeTextFile(\`\${mate}/README.md\`, "teammate's version\\n");
await run("git", ["add", "-A"], mate);
await run("git", [...WHO, "commit", "-m", "readme from teammate"], mate);
await run("git", [...WHO, "push", "origin", "master"], mate);

await Deno.writeTextFile(\`\${work}/README.md\`, "my version\\n");
await run("git", ["add", "-A"], work);
await run("git", [...WHO, "commit", "-m", "readme from me"], work);
const rejected = await run("git", [...WHO, "push", "origin", "master"], work);
console.log(\`\\n  push rejected? \${/rejected|failed/i.test(rejected) ? "YES" : "no"}\`);
console.log("  Git refuses rather than silently discarding their commit.");
console.log("  The fix is the rule: pull first, resolve, then push.");

console.log("\\n=== 12. git log — the history you built ===");
await run("git", ["log", "--oneline"], work);

await Deno.remove(root, { recursive: true });
console.log("\\n(temp folders removed)");
`);

// Run it the way you would from a terminal.
const proc = new Deno.Command("deno", {
  args: ["run", "-A", "week6/generated/day3-git-walkthrough.ts"],
  cwd: REPO_ROOT,
  stdout: "piped",
  stderr: "piped",
});
const { stdout, stderr } = await proc.output();
console.log(new TextDecoder().decode(stdout) + new TextDecoder().decode(stderr));

// Which branch is THIS repository on? Run it rather than assuming.
const branch = new Deno.Command("git", {
  args: ["branch", "--show-current"],
  stdout: "piped",
});
const branchOut = await branch.output();
console.log("this repo's branch:", new TextDecoder().decode(branchOut.stdout).trim());

// This repo's own .gitignore, and proof the auth file is covered.
import { REPO_ROOT } from "../_shared/deno-helpers.ts";

// REPO_ROOT, not "..": the kernel's cwd is wherever Jupyter was started.
const ignoreFile = await Deno.readTextFile(`${REPO_ROOT}/.gitignore`);
console.log(ignoreFile.trim());

const check = new Deno.Command("git", {
  args: ["check-ignore", "-v", "week5/generated/.auth/saucedemo.json"],
  cwd: REPO_ROOT,
  stdout: "piped",
  stderr: "piped",
});
const checked = await check.output();
console.log("\ngit check-ignore says:");
console.log(new TextDecoder().decode(checked.stdout).trim() || "(not ignored!)");

// Why a leaked credential is not fixed by deleting the file.
const secretRoot = await Deno.makeTempDir({ prefix: "week6-secret-" });
const gitWho = ["-c", "user.email=l@e.com", "-c", "user.name=l"];

async function g(args: string[]): Promise<string> {
  const c = new Deno.Command("git", { args, cwd: secretRoot, stdout: "piped", stderr: "piped" });
  const o = await c.output();
  return (new TextDecoder().decode(o.stdout) + new TextDecoder().decode(o.stderr)).trim();
}

await g(["init", "-q", "-b", "main", "."]);
await Deno.writeTextFile(`${secretRoot}/.env`, "TOKEN=super-secret-value");
await g(["add", "-A"]);
await g([...gitWho, "commit", "-q", "-m", "oops, committed the token"]);

// Now "remove" it, the way people do.
await Deno.remove(`${secretRoot}/.env`);
await g(["add", "-A"]);
await g([...gitWho, "commit", "-q", "-m", "remove .env"]);

console.log("working copy still has .env?",
  await Deno.stat(`${secretRoot}/.env`).then(() => "yes").catch(() => "no"));

const history = await g(["log", "-p", "--all"]);
console.log("token still recoverable from history?",
  history.includes("super-secret-value") ? "YES - it is still there" : "no");

await Deno.remove(secretRoot, { recursive: true });
